class DeterministicTestRunner:
    """Custom runner ensuring deterministic test execution."""
    
    def __init__(self, seed: int = 42):
        self.seed = seed
        self._rng = random.Random(seed)
    
    def shuffle_tests(self, tests: list) -> list:
        """Deterministically shuffle test order."""
        shuffled = tests.copy()
        self._rng.shuffle(shuffled)
        return shuffled
    
    def run(self, test_paths: list[str]) -> int:
        """Execute tests with deterministic ordering."""
        args = [
            "-p", "no:cacheprovider",
            "--tb=short",
            "-q",
            *test_paths
        ]
        return pytest.main(args)


